(* [comment removed for export] *)
Lemma ru_A1g_run : forall regs m (DX DW DPW : Z),
  (- 2 ^ 24 <= DX <= 2 ^ 24)%Z -> (0 <= DW <= 2 ^ 24)%Z -> (0 <= DPW <= 2 ^ 24)%Z ->
  getr regs 14 = Z_to_bv 64 DX -> getr regs 13 = Z_to_bv 64 DW -> getr regs 11 = Z_to_bv 64 DPW ->
  exists regs',
    msteps SEGS (mkst regs (0x79a90 : word) m rom) (mkst regs' (0x79ac0 : word) m rom)
    /\ getr regs' 13 = Z_to_bv 64 (Z.max 0 DX) /\ getr regs' 18 = Z_to_bv 64 (uclip_w DX DW DPW)
    /\ regs_agree (fun r => In r [11; 13; 14; 15; 18]%list) regs regs'.
